module TopModule (
    input  logic       clk,
    input  logic       x,
    input  logic [2:0] y,
    output logic       Y0,
    output logic       z
);

  logic [2:0] next_y;

  // Prevent unused clk warning if not used in combinational logic
  wire unused_clk = clk;

  always_comb begin
    next_y = 3'b000;
    case (y)
      3'b000: next_y = x ? 3'b001 : 3'b000;
      3'b001: next_y = x ? 3'b100 : 3'b001;
      3'b010: next_y = x ? 3'b001 : 3'b010;
      3'b011: next_y = x ? 3'b010 : 3'b001;
      3'b100: next_y = x ? 3'b100 : 3'b011;
      default: next_y = 3'b000;
    endcase
  end

  assign Y0 = next_y[0];
  assign z  = y[2] | (y[1] & y[0]);

endmodule

